    if (!xmlString) return null;
    try {
        let mathEl = null;
        try {
            const xmlDoc = new DOMParser().parseFromString('<root>' + xmlString + '</root>', 'text/xml');
            mathEl = xmlDoc.querySelector('math');
        } catch {}
        if (!mathEl) {
            const htmlDoc = new DOMParser().parseFromString(xmlString, 'text/html');
            mathEl = htmlDoc.querySelector('math');
        }
        if (mathEl) {
            const omml = mathMlToOmmlEl(mathEl);
            return omml ? '<m:oMath>' + omml + '</m:oMath>' : null;
        }
        return null;
    } catch {
        return null;
    }
