    div.querySelectorAll('.formula-latex, [data-latex]').forEach(el => {
        const latex = el.getAttribute('data-latex') || el.getAttribute('latex') || el.textContent;
        const omml = latexToOmml(latex);
        if (omml) {
            el.replaceWith(document.createTextNode(ommlSlot(omml)));
        }
    });

