function extractStyleProp(el, propName) {
    let cur = el;
    while (cur && cur.nodeType === 1) {
        if (cur.getAttribute) {
            const direct = cur.getAttribute(propName);
            if (direct) return direct.trim();
            const styleAttr = cur.getAttribute('style') || '';
            if (styleAttr) {
                const re = new RegExp('(?:^|;)\\s*' + propName + '\\s*:\\s*([^;]+)', 'i');
                const m = re.exec(styleAttr);
                if (m) return m[1].trim();
            }
        }
        cur = cur.parentElement || cur.parentNode;
    }
    return '';
}

function parseNumList(str) {
    if (!str || !String(str).trim()) return [];
    const m = String(str).trim().match(/[-+]?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?/gi);
    return m ? m.map(Number) : [];
}

